1	/**
2	 * The npm scripts that drive the workspace, retargeted onto the flags the
3	 * migrated workspace and the cell's CLI line still accept.
4	 *
5	 * A workspace migration rewrites the document the build is *configured* by and
6	 * leaves the command line that *invokes* it exactly where it was. For most of a
7	 * manifest that is correct — a script is a project's own sentence and not a
8	 * schema — but two classes of flag stop being sentences and become defects the
9	 * moment the workspace beneath them changes:
10	 *
11	 * - a flag that sets a builder option the workspace migration just removed, and
12	 * - a flag the CLI line the cell targets no longer parses at all.
13	 *
14	 * Either one turns a build script into an immediate refusal from the CLI's own
15	 * argument parser, and neither is visible in a changeset that reports only the
16	 * workspace document. The measured case is one line of one application:
17	 * `ng build --prod --aot --extract-css`, where `extractCss` was removed from the
18	 * production configuration by the workspace migration in the same changeset and
19	 * `--prod` was removed from the CLI after the 11 line.
20	 *
21	 * ## What gates it
22	 *
23	 * Nothing here rewrites a script because it looks like a build. Three detectors
24	 * have to agree before a byte moves:
25	 *
26	 * - the command segment has to *invoke the workspace's own CLI binary* — its
27	 *   first word is `ng` — because a flag spelled the same way on another program
28	 *   means whatever that program says it means,
29	 * - a dropped flag has to name a builder option this workspace migration actually
30	 *   removed, read from the migration's own changes rather than from a list of
31	 *   flags that were removed somewhere at some point, and
32	 * - a retargeted flag has to be one the cell's Angular major is past, and its
33	 *   replacement has to name a configuration the migrated workspace really
34	 *   declares.
35	 *
36	 * Everything else is reported rather than rewritten: a script whose command this
37	 * cannot parse without guessing — a quoted segment, a flag that may be carrying a
38	 * separate value — is left byte-identical and named in `unhandled`, because a
39	 * half-rewritten command line is worse than one that fails honestly.
40	 */
41	
42	import { compareStrings, majorOf, type AngularTargetCell, type PackageManifest } from './angular-target-cell.ts';
43	import { REMOVED_BUILDER_OPTIONS, type ConfigChange } from './angular-workspace-migration.ts';
44	
45	/** The npm script field this capability reads. */
46	const SCRIPTS_FIELD = 'scripts';
47	
48	/** The workspace's own CLI binary, as a script's first word. */
49	export const ANGULAR_CLI_BINARY = 'ng';
50	
51	/**
52	 * A flag the Angular CLI stopped parsing, and what it became.
53	 *
54	 * This is a reading of the CLI's own flag surface, kept here rather than on the
55	 * cell because it is a fact about the tool the cell names rather than about the
56	 * package versions the cell writes. `removedAfterMajor` is the last CLI major
57	 * that accepted the flag, so a cell on that major or below leaves it alone: the
58	 * capability stands down on a hop that does not cross the removal.
59	 */
60	export type RemovedCliFlag = Readonly<{
61		flag: string;
62		removedAfterMajor: number;
63		/** The spelling that replaces it, or null when the flag simply went away. */
64		successor: string | null;
65		/**
66		 * The configuration name the successor selects, when the successor is a
67		 * configuration selection. The retarget is refused unless the migrated
68		 * workspace really declares it.
69		 */
70		requiresConfiguration?: string;
71		fact: string;
72	}>;
73	
74	export const REMOVED_ANGULAR_CLI_FLAGS: readonly RemovedCliFlag[] = Object.freeze([
75		Object.freeze({
76			flag: '--prod',
77			removedAfterMajor: 11,
78			successor: '--configuration production',
79			requiresConfiguration: 'production',
80			fact: '`--prod` was a shorthand for `--configuration production` and was removed from the Angular CLI after the 11 line; a 12-or-later CLI reports it as an unknown argument and exits before the builder runs. The replacement selects the same configuration by name, which is why the retarget is refused where the migrated workspace does not declare one.',
81		}),
82	]);
83	
84	export type ScriptFlagChange = Readonly<{
85		kind: 'removed-builder-flag' | 'retargeted-cli-flag';
86		/** The npm script the flag was written in. */
87		script: string;
88		/** The flag exactly as the era script wrote it. */
89		from: string;
90		/** What replaced it, or null when it was dropped. */
91		to: string | null;
92		reason: string;
93	}>;
94	
95	export type WorkspaceScriptMigration = Readonly<{
96		manifest: PackageManifest;
97		changes: readonly ScriptFlagChange[];
98		unhandled: readonly string[];
99	}>;
100	
101	function objectAt(value: unknown): Readonly<Record<string, unknown>> | null {
102		if (typeof value !== 'object' || value === null || Array.isArray(value)) return null;
103		return value as Readonly<Record<string, unknown>>;
104	}
105	
106	/** camelCase as a command-line flag spells it: `extractCss` -> `--extract-css`. */
107	export function optionFlagSpelling(option: string): string {
108		let spelled = '';
109		for (const character of option) {
110			const lower = character.toLowerCase();
111			if (lower !== character) spelled += '-';
112			spelled += lower;
113		}
114		return `--${spelled}`;
115	}
116	
117	/**
118	 * The flags whose builder option *this* workspace migration removed.
119	 *
120	 * Read from the migration's own changes so the set is a fact about this
121	 * workspace: an option the era document never declared is not in it, and a
122	 * script that passes the matching flag anyway is left alone and reported. The
123	 * change has to be a removal (`to === null`) of a key the builder schema is
124	 * known to have dropped, which is what keeps an unrelated removal — a
125	 * `defaultProject`, a lint target — from inventing a flag rule.
126	 */
127	export function removedBuilderOptionFlags(
128		changes: readonly ConfigChange[],
129	): Readonly<Record<string, string>> {
130		const flags: Record<string, string> = {};
131		for (const change of changes) {
132			if (change.to !== null) continue;
133			const option = change.path.split('.').at(-1) ?? '';
134			if (!REMOVED_BUILDER_OPTIONS.includes(option)) continue;
135			flags[optionFlagSpelling(option)] = change.path;
136		}
137		return Object.freeze(flags);
138	}
139	
140	/** Every configuration name the migrated workspace declares, across its targets. */
141	export function declaredConfigurationNames(workspaceConfig: string): readonly string[] {
142		let parsed: unknown;
143		try {
144			parsed = JSON.parse(workspaceConfig) as unknown;
145		} catch {
146			return Object.freeze([]);
147		}
148		const names = new Set<string>();
149		const projects = objectAt(objectAt(parsed)?.['projects']);
150		for (const project of Object.values(projects ?? {})) {
151			const entry = objectAt(project);
152			if (entry === null) continue;
153			const architect = objectAt(entry['architect']) ?? objectAt(entry['targets']);
154			for (const target of Object.values(architect ?? {})) {
155				const configurations = objectAt(objectAt(target)?.['configurations']);
156				for (const name of Object.keys(configurations ?? {})) names.add(name);
157			}
158		}
159		return Object.freeze([...names].sort(compareStrings));
160	}
161	
162	/** True for a command segment this capability declines to take apart. */
163	function isUnparseableSegment(segment: string): boolean {
164		return segment.includes('"') || segment.includes("'") || segment.includes('`');
165	}
166	
167	type SegmentRewrite = Readonly<{
168		segment: string;
169		changes: readonly ScriptFlagChange[];
170		unhandled: readonly string[];
171	}>;
172	
173	function rewriteSegment(
174		script: string,
175		segment: string,
176		removedFlags: Readonly<Record<string, string>>,
177		cell: AngularTargetCell,
178		configurations: readonly string[],
179	): SegmentRewrite {
180		const tokens = segment.split(' ').filter((token) => token !== '');
181		if (tokens[0] !== ANGULAR_CLI_BINARY)
182			return Object.freeze({ segment, changes: Object.freeze([]), unhandled: Object.freeze([]) });
183		const cellMajor = majorOf(cell.angularLine);
184		const changes: ScriptFlagChange[] = [];
185		const unhandled: string[] = [];
186		const written: string[] = [];
187		for (let index = 0; index < tokens.length; index += 1) {
188			const token = tokens[index] as string;
189			if (!token.startsWith('--')) {
190				written.push(token);
191				continue;
192			}
193			const carriesValue = token.includes('=');
194			const next = tokens[index + 1];
195			const separatedValue = !carriesValue && next !== undefined && !next.startsWith('-');
196			const removedFrom = removedFlags[token];
197			if (removedFrom !== undefined) {
198				if (carriesValue || separatedValue) {
199					written.push(token);
200					unhandled.push(
201						`${SCRIPTS_FIELD}.${script} passes ${token}, whose builder option this migration ` +
202							`removed at ${removedFrom}, and the flag is written with a value. The script was left ` +
203							'byte-identical: dropping a flag without knowing whether the word after it is that ' +
204							"flag's value would rewrite the command into a different one.",
205					);
206					continue;
207				}
208				changes.push(
209					Object.freeze({
210						kind: 'removed-builder-flag' as const,
211						script,
212						from: token,
213						to: null,
214						reason:
215							`${token} sets a builder option this migration removed from the workspace at ` +
216							`${removedFrom}; the ${cell.builder} of ${cell.id} rejects the option, so the script ` +
217							'that passes it would be refused by the builder schema before the build began.',
218					}),
219				);
220				continue;
221			}
222			const removedFlag = REMOVED_ANGULAR_CLI_FLAGS.find((entry) => entry.flag === token);
223			if (removedFlag === undefined) {
224				written.push(token);
225				continue;
226			}
227			if (cellMajor === null || cellMajor <= removedFlag.removedAfterMajor) {
228				written.push(token);
229				continue;
230			}
231			if (
232				removedFlag.requiresConfiguration !== undefined &&
233				!configurations.includes(removedFlag.requiresConfiguration)
234			) {
235				written.push(token);
236				unhandled.push(
237					`${SCRIPTS_FIELD}.${script} passes ${token}, which the Angular CLI removed after the ` +
238						`${String(removedFlag.removedAfterMajor)} line, and its replacement selects the ` +
239						`"${removedFlag.requiresConfiguration}" configuration, which the migrated workspace does ` +
240						'not declare. The script was left as it is rather than pointed at a configuration that ' +
241						'does not exist.',
242				);
243				continue;
244			}
245			if (removedFlag.successor === null) {
246				changes.push(
247					Object.freeze({
248						kind: 'retargeted-cli-flag' as const,
249						script,
250						from: token,
251						to: null,
252						reason: removedFlag.fact,
253					}),
254				);
255				continue;
256			}
257			written.push(...removedFlag.successor.split(' '));
258			changes.push(
259				Object.freeze({
260					kind: 'retargeted-cli-flag' as const,
261					script,
262					from: token,
263					to: removedFlag.successor,
264					reason: removedFlag.fact,
265				}),
266			);
267		}
268		return Object.freeze({
269			segment: written.join(' '),
270			changes: Object.freeze(changes),
271			unhandled: Object.freeze(unhandled),
272		});
273	}
274	
275	/**
276	 * Retarget the workspace's own npm scripts onto the migrated workspace.
277	 *
278	 * The manifest handed here is the migrated one, and the changes handed here are
279	 * the workspace migration's own: this capability decides nothing about which
280	 * builder options survive, it only carries what that decision means for the
281	 * command lines that invoke them. A manifest with no `scripts` block has nothing
282	 * retargeted, and so does a workspace migration that removed no builder option
283	 * and a cell whose CLI line still parses every flag the scripts write.
284	 */
285	export function retargetWorkspaceScripts(
286		manifest: PackageManifest,
287		workspaceChanges: readonly ConfigChange[],
288		cell: AngularTargetCell,
289		migratedWorkspaceConfig = '',
290	): WorkspaceScriptMigration {
291		const scripts = objectAt(manifest[SCRIPTS_FIELD]);
292		if (scripts === null)
293			return Object.freeze({
294				manifest,
295				changes: Object.freeze([]),
296				unhandled: Object.freeze([]),
297			});
298		const removedFlags = removedBuilderOptionFlags(workspaceChanges);
299		const configurations = declaredConfigurationNames(migratedWorkspaceConfig);
300		const changes: ScriptFlagChange[] = [];
301		const unhandled: string[] = [];
302		const next: Record<string, unknown> = {};
303		for (const [script, command] of Object.entries(scripts)) {
304			if (typeof command !== 'string') {
305				next[script] = command;
306				continue;
307			}
308			const separator = '&&';
309			const segments = command.split(separator);
310			if (!segments.some((segment) => segment.trim().startsWith(`${ANGULAR_CLI_BINARY} `))) {
311				next[script] = command;
312				continue;
313			}
314			if (isUnparseableSegment(command)) {
315				next[script] = command;
316				unhandled.push(
317					`${SCRIPTS_FIELD}.${script} invokes ${ANGULAR_CLI_BINARY} inside a quoted command this ` +
318						'migration does not take apart, so it was left byte-identical. Whether the flags it ' +
319						'passes are still accepted by the migrated workspace is unestablished.',
320				);
321				continue;
322			}
323			const rewritten: string[] = [];
324			const scriptChanges: ScriptFlagChange[] = [];
325			for (const segment of segments) {
326				const trimmed = segment.trim();
327				const result = rewriteSegment(script, trimmed, removedFlags, cell, configurations);
328				scriptChanges.push(...result.changes);
329				unhandled.push(...result.unhandled);
330				rewritten.push(result.segment);
331			}
332			changes.push(...scriptChanges);
333			next[script] =
334				scriptChanges.length === 0 ? command : rewritten.join(` ${separator} `).trim();
335		}
336		return Object.freeze({
337			manifest: Object.freeze({ ...manifest, [SCRIPTS_FIELD]: Object.freeze(next) }),
338			changes: Object.freeze(changes),
339			unhandled: Object.freeze(unhandled),
340		});
341	}
